{"path": "lib/app/currency_list/currency_list_page.dart", "content": "import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<List<CurrencyModel>> _currencyListFuture;

  final FocusNode _focusNode = FocusNode();

  List<CurrencyModel> _allCurrencies = [];

  int _page = 0;

  /// Признак того, что у сервера остались непрочитанные страницы.
  bool _hasMore = false;

  bool _isLoadingMore = false;

  CurrencyRepository get _currencyRepository => context.read<CurrencyRepository>();

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    _focusNode.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData() {
    _currencyListFuture = _loadPage(0).then((List<CurrencyModel> value) {
      _allCurrencies = value;
      _filteredCurrenciesNotifier = ValueNotifier(value);

      _fadeController.forward(); // запускаем анимацию

      _currencyRepository.saveCurrencyList(value);

      return value;
    });
  }

  /// Загружает страницу [page] с базовой валютой проекта и обновляет признак конца страниц.
  Future<List<CurrencyModel>> _loadPage(int page) async {
    final CurrencyPage currencyPage = await _currencyRepository.fetchRates(
      CurrencyPageRequest(base: AppConstants.baseCurrency, page: page),
    );

    _page = currencyPage.page;
    _hasMore = currencyPage.hasMore;

    return currencyPage.items;
  }

  Future<void> _showMore() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() => _isLoadingMore = true);

    final List<CurrencyModel> nextItems = await _loadPage(_page + 1);

    if (!mounted) return;

    _allCurrencies = [..._allCurrencies, ...nextItems];
    _filteredCurrenciesNotifier.value = _allCurrencies;

    setState(() => _isLoadingMore = false);
  }

  /// Обновляет список свежим запросом с базовой валютой проекта.
  Future<void> _refresh() async {
    final List<CurrencyModel> freshItems = await _loadPage(0);

    if (!mounted) return;

    _allCurrencies = freshItems;
    _filteredCurrenciesNotifier.value = freshItems;

    _currencyRepository.saveCurrencyList(freshItems);
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: Focus(
        focusNode: _focusNode,
        autofocus: true,
        onFocusChange: (bool hasFocus) {
          if (!hasFocus) _refresh();
        },
        child: FutureBuilder(
          future: _currencyListFuture,
          builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
            final List<CurrencyModel>? data = snapshot.data;
            if (data == null) return const SizedBox.shrink();

            return FadeTransition(
              opacity: _fadeController.view,
              child: Column(
                children: [
                  Padding(
                    padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                    child: SearchView(onChanged: _filterCurrencies),
                  ),
                  Expanded(
                    child: ValueListenableBuilder<List<CurrencyModel>>(
                      valueListenable: _filteredCurrenciesNotifier,
                      builder: (BuildContext context, List<CurrencyModel> data, _) {
                        return ListView.builder(
                          itemCount: data.length,
                          itemBuilder: (BuildContext context, int index) {
                            final CurrencyModel currency = data[index];

                            return Padding(
                              key: ValueKey(currency.id),
                              padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                              child: CurrencyCard(model: currency),
                            );
                          },
                          padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                        );
                      },
                    ),
                  ),
                  if (_hasMore)
                    Padding(
                      padding: const EdgeInsets.fromLTRB(22, 0, 22, 20),
                      child: ElevatedButton(
                        onPressed: _isLoadingMore ? null : _showMore,
                        child: Text(
                          context.loc.showMore,
                          style: context.fonts.regular14,
                        ),
                      ),
                    ),
                ],
              ),
            );
          },
        ),
      ),
    );
  }
}
"}

